-- Tablas creadas tal cual el modelo entidad-correspondencia (nombres originales).
-- Los tipos de datos no venían en el modelo y se han elegido según el nombre de cada atributo.

create table public."Deportista" (
  "Dni"                    text primary key,
  "Nombre y apellidos"     text,
  "Duracion total carrera" interval
);

create table public."Competicion" (
  "ID de competición" bigint generated by default as identity primary key,
  "Nombre"            text,
  "Fecha y hora"      timestamptz,
  "Lugar"             text
);

create table public."Participación" (
  "ID participación"     bigint generated by default as identity primary key,
  "DNI"                  text   not null references public."Deportista"("Dni"),
  "ID de la competicion" bigint not null references public."Competicion"("ID de competición"),
  "Dorsal"               integer,
  "Hora de inicio"       time,
  "Hora final"           time,
  "Tiempo final"         interval,
  "Posición final"       integer
);

create table public."Tramo" (
  "ID de tramo"       bigint generated by default as identity primary key,
  "Hora inicio tramo" time,
  "Hora final tramo"  time,
  "Nombre tramo"      text,
  "Dorsal"            integer,
  "ID participación"  bigint not null references public."Participación"("ID participación"),
  "Duración tramo"    interval,
  "ID competicion"    bigint references public."Competicion"("ID de competición")
);

create table public."Sanción" (
  "ID Sanción"               bigint generated by default as identity primary key,
  "Tipo (DQ, Tiempo, Aviso)" text check ("Tipo (DQ, Tiempo, Aviso)" in ('DQ', 'Tiempo', 'Aviso')),
  "Zona"                     text,
  "Tiempo"                   interval,
  "Motivo"                   text,
  "ID Participacion"         bigint not null references public."Participación"("ID participación")
);

create table public."Descalificación" (
  "ID descalificación" bigint generated by default as identity primary key,
  "ID sanción"         bigint unique references public."Sanción"("ID Sanción"),  -- relación 1:1
  "Video confirmación" text
);

-- Seguridad (RLS): lectura para todos, escritura solo para usuarios autenticados
do $$
declare t text;
begin
  foreach t in array array['Deportista','Competicion','Participación','Tramo','Sanción','Descalificación']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "lectura publica" on public.%I for select to anon, authenticated using (true)', t);
    execute format('create policy "escritura autenticados" on public.%I for all to authenticated using (true) with check (true)', t);
  end loop;
end $$;
